148	const INGEST_NOT_ESTABLISHED: readonly string[] = Object.freeze([
149		'An ingest record states what the source on disk says at the revision it was pinned to. It is not an acquisition: nothing here establishes that these bytes are the bytes the named repository publishes at that revision, and no archive was fetched, reconciled against a Git tree, or double-streamed by this stage.',
