178	/**
179	 * The commit a checkout is sitting on, read from its own Git metadata.
180	 *
181	 * Returns the sha and the file it came out of, or `null` when the tree carries
182	 * no readable Git metadata — which is a refusal upstream, not a default.
183	 */
184	export async function readGitRevision(
185		sourceRoot: string,
186	): Promise<Readonly<{ commitSha: string; readFrom: string }> | null> {
187		const gitDir = path.join(sourceRoot, '.git');
188		if (!(await directoryExists(gitDir))) return null;
189		const headFile = path.join(gitDir, 'HEAD');
190		if (!(await fileExists(headFile))) return null;
191		const head = (await readFile(headFile, 'utf8')).trim();
192		if (!head.startsWith('ref: '))
193			return lowerHex40.test(head) ? { commitSha: head, readFrom: '.git/HEAD' } : null;
194		const reference = head.slice('ref: '.length).trim();
195		const looseFile = path.join(gitDir, reference);
196		if (await fileExists(looseFile)) {
197			const sha = (await readFile(looseFile, 'utf8')).trim();
198			if (lowerHex40.test(sha)) return { commitSha: sha, readFrom: `.git/${reference}` };
199			return null;
200		}
201		const packedFile = path.join(gitDir, 'packed-refs');
202		if (!(await fileExists(packedFile))) return null;
203		for (const line of (await readFile(packedFile, 'utf8')).split('\n')) {
204			if (line.startsWith('#') || line.startsWith('^')) continue;
205			const [sha, name] = line.trim().split(' ');
206			if (name === reference && sha !== undefined && lowerHex40.test(sha))
207				return { commitSha: sha, readFrom: '.git/packed-refs' };
208		}
209		return null;
210	}
