212	/**
213	 * The lane layout the acquire stage writes: `<root>/.versionless/work/<id>/baseline`
214	 * for the tree, `<root>/evidence/ingests/<id>/source.json` for the journal.
215	 *
216	 * Reading the layout is how this stage finds the journal that belongs to a tree
217	 * it was handed. A source root that is not a lane baseline yields nothing here,
218	 * which leaves the revision unread rather than guessed at.
219	 */
220	export function acquisitionLaneOf(
221		sourceRoot: string,
222	): Readonly<{ workspaceRoot: string; laneId: string }> | null {
223		const segments = path.resolve(sourceRoot).split('/');
224		if (segments.length < 5) return null;
225		const [marker, work, laneId, baseline] = segments.slice(-4) as [string, string, string, string];
226		if (marker !== '.versionless' || work !== 'work' || baseline !== 'baseline') return null;
227		if (laneId === '') return null;
228		return Object.freeze({ workspaceRoot: segments.slice(0, -4).join('/'), laneId });
229	}
