231	/**
232	 * The acquisition journal for a tree, read from the pipeline's own evidence.
233	 *
234	 * `acquire` resolves the revision through a consented transaction, reconciles
235	 * the archive against the Git tree the repository publishes, and journals both
236	 * to `evidence/ingests/<id>/source.json`. This reads that journal — nothing is
237	 * fetched and no socket is opened — and returns it unjudged; the gates below
238	 * decide whether it is a reading of *this* tree.
239	 */
240	async function readAcquisitionJournal(
241		sourceRoot: string,
242		ingestId: string,
243	): Promise<Readonly<{ file: string; document: Record<string, unknown> }> | null> {
244		const lane = acquisitionLaneOf(sourceRoot);
245		if (lane === null) return null;
246		const seen = new Set<string>();
247		for (const candidate of [lane.laneId, ingestId]) {
248			if (candidate === '' || seen.has(candidate)) continue;
249			seen.add(candidate);
250			const relative = `evidence/ingests/${candidate}/source.json`;
251			const file = path.join(lane.workspaceRoot, relative);
252			if (!(await fileExists(file))) continue;
253			const document = await readJsonFile(file);
254			if (document === null) continue;
255			return Object.freeze({ file: relative, document });
256		}
257		return null;
258	}
