260	const stringAt = (document: Record<string, unknown>, ...keys: readonly string[]): string | null => {
261		let current: unknown = document;
262		for (const key of keys) {
263			if (current === null || typeof current !== 'object') return null;
264			current = (current as Record<string, unknown>)[key];
265		}
266		return typeof current === 'string' && current.trim() !== '' ? current.trim() : null;
267	};
