271	 *
272	 * Four gates, and every one of them refuses rather than degrades. A journal
273	 * whose transaction did not bind a source is not a pin; a journal carrying no
274	 * consent identifier is not a consented reading; a journal carrying no parity
275	 * basis — the archive reconciled against the published Git tree, byte-identical
276	 * across two streams — states no relationship between the bytes and the commit;
277	 * and a journal whose manifest digest is not this tree's digest is a reading of
278	 * some other bytes.
279	 */
280	function revisionOfAcquisitionJournal(
281		file: string,
282		document: Record<string, unknown>,
283		tree: IngestTreeReading,
284	): Readonly<{ commitSha: string; readFrom: string }> {
285		const result = stringAt(document, 'result');
286		if (result !== 'source-bound')
287			refuse({
288				code: 'ingest.acquisition-journal-not-source-bound',
289				message: `Ingest: ${file} records the acquisition of this tree with result ${result ?? 'none'} rather than source-bound. Only a transaction that bound a source states a revision these bytes are pinned to, so this stage reads no pin out of it; declare the revision with --revision <commit-sha> if you know it by other means.`,
290				stage: 'ingest',
291				origin: 'pipeline',
292			});
293		const consentId = stringAt(document, 'consentId');
294		if (consentId === null)
295			refuse({
296				code: 'ingest.acquisition-journal-carries-no-consent',
297				message: `Ingest: ${file} names no consentId, so nothing in it says under whose consent the network was opened. A journal without consent is not a reading this stage adopts a pin from.`,
298				stage: 'ingest',
299				origin: 'pipeline',
300			});
301		const journalled = stringAt(document, 'archiveParity', 'normalizedManifestSha256');
302		const transaction = document.transaction as Record<string, unknown> | undefined;
303		const matchesGitTree = transaction?.archiveMatchesGitTree === true;
304		const byteIdentical = transaction?.archivesByteIdentical === true;
305		if (journalled === null || !matchesGitTree || !byteIdentical)
306			refuse({
307				code: 'ingest.acquisition-journal-carries-no-parity-basis',
308				message: `Ingest: ${file} carries no parity basis — archiveMatchesGitTree ${String(matchesGitTree)}, archivesByteIdentical ${String(byteIdentical)}, archive manifest ${journalled ?? 'unrecorded'}. A journal that did not reconcile its archive against the Git tree the repository publishes establishes no relationship between these bytes and the commit it names, so this stage reads no pin out of it.`,
309				stage: 'ingest',
310				origin: 'pipeline',
311			});
312		const commitSha = stringAt(document, 'revision', 'commitSha');
313		if (commitSha === null || !lowerHex40.test(commitSha))
314			refuse({
315				code: 'ingest.acquisition-journal-revision-unreadable',
316				message: `Ingest: ${file} records the revision ${commitSha ?? 'none'}, which is not a 40-character lower-case hexadecimal commit sha. The pin is what the licence reading and every later record are relative to, so an abbreviated or symbolic revision is refused rather than resolved into one.`,
317				stage: 'ingest',
318				origin: 'pipeline',
319			});
320		if (journalled !== tree.normalizedManifestSha256)
321			refuse({
322				code: 'ingest.acquisition-journal-does-not-match-the-tree',
323				message: `Ingest: ${file} journalled the manifest digest ${journalled} for the source it acquired, and the tree on disk walks to ${tree.normalizedManifestSha256}. These are not the same bytes, so the revision that journal names is not the revision this tree is sitting at; re-acquire the source, or declare the revision with --revision <commit-sha>.`,
324				stage: 'ingest',
325				origin: 'pipeline',
326			});
327		return Object.freeze({
328			commitSha,
329			readFrom: `${file} (consent ${consentId}; result source-bound; archive reconciled against the published Git tree and byte-identical across two streams; journalled manifest ${journalled} is the digest this stage walked)`,
330		});
331	}
