333	/**
334	 * The one immediate subdirectory carrying a manifest, or `null`.
335	 *
336	 * Zero and more than one are both refusals upstream. "Pick the first" is
337	 * exactly the kind of default this stage exists to not take.
338	 */
339	async function manifestBearingSubdirectories(sourceRoot: string): Promise<readonly string[]> {
340		const found: string[] = [];
341		let entries: string[];
342		try {
343			entries = (await readdir(sourceRoot, { withFileTypes: true }))
344				.filter((entry) => entry.isDirectory())
345				.map((entry) => entry.name)
