347		} catch {
348			return Object.freeze([]);
349		}
350		for (const name of entries) {
351			if (name === 'node_modules' || name === '.git') continue;
352			if (await fileExists(path.join(sourceRoot, name, 'package.json'))) found.push(name);
353		}
354		return Object.freeze(found);
