357	async function readTree(sourceRoot: string): Promise<IngestTreeReading> {
358		const relatives = await workspacePathsBelow(sourceRoot, sourceRoot);
359		const files: ExtractedFile[] = [];
360		let bytes = 0;
361		for (const relative of relatives) {
362			const contents = await readFile(path.join(sourceRoot, relative));
363			bytes += contents.byteLength;
364			files.push({ path: relative, bytes: contents });
365		}
366		return Object.freeze({
367			files: files.length,
368			bytes,
369			normalizedManifestSha256: normalizedManifest(files).sha256,
370		});
371	}
