/**
 * The lane layout the acquire stage writes: `<root>/.versionless/work/<id>/baseline`
 * for the tree, `<root>/evidence/ingests/<id>/source.json` for the journal.
 *
 * Reading the layout is how this stage finds the journal that belongs to a tree
 * it was handed. A source root that is not a lane baseline yields nothing here,
 * which leaves the revision unread rather than guessed at.
 */
export function acquisitionLaneOf(
	sourceRoot: string,
): Readonly<{ workspaceRoot: string; laneId: string }> | null {
	const segments = path.resolve(sourceRoot).split('/');
	if (segments.length < 5) return null;
	const [marker, work, laneId, baseline] = segments.slice(-4) as [string, string, string, string];
	if (marker !== '.versionless' || work !== 'work' || baseline !== 'baseline') return null;
	if (laneId === '') return null;
	return Object.freeze({ workspaceRoot: segments.slice(0, -4).join('/'), laneId });
}

