			'era-cell',
			'plan',
			'apply',
			'install',
			'build',
			'witness',
		] as const) {
			expect(rows.get(name)?.status).toBe('not-run');
			expect(rows.get(name)?.reason).toBe('not-run-because: ingest refused');
		}
		/** Nothing after the refusal wrote a lane. */
		expect(await exists(lane)).toBe(false);
	});

